/// <summary>
/// 寫回並組成回應。儲存或移除時，其他情境都合格、已是目前規則而且存好的結果沒有過期，就只寫這一個：
/// 儲存只算這一個情境的結果，移除只刪這一個的定義與結果，其他情境不重新檢查版本也不重算。
/// 否則照整批處理：全部合格時由 <see cref="IFilterFactsPort"/> 一次寫入定義與命中，篩選結果的過期旗標也清掉，並把案件至少推進到 <paramref name="advancesTo"/> 這一步；
/// 有不合格的情境時只寫定義，同一筆交易清掉命中並標成失效，結果維持鎖住。
/// 清單是空的而且不必寫入（重新檢查時沒有情境）就直接回應。
/// </summary>
internal static async Task<object> PublishAsync(
    string action,
    WorkflowStep advancesTo,
    IProjectStore projectStore,
    FilterScenarioStores stores,
    Prepared prepared,
    Change change,
    bool skipWhenEmpty,
    DateTimeOffset nowUtc,
    ILogger? logger,
    CancellationToken cancellationToken)
{
    var resultsCurrent = !(await stores.StaleStates.ReadAsync(prepared.ProjectId, cancellationToken)).Filter;
    var write = FilterScenarioRuleUpgrade.PlanWrite(
        change.Batch,
        change.EditedPosition,
        change.Mode,
        prepared.Validation,
        prepared.Document.MoneyScale,
        nowUtc,
        othersResultsCurrent: resultsCurrent);
    FilterScenarioDiagnostics.LogProblems(logger, action, write.Problems);

    if (!(skipWhenEmpty && write.Rows.Count == 0))
    {
        if (write.KeepsOtherResults)
        {
            if (change.EditedPosition is int edited)
            {
                var row = write.Rows[edited - 1];
                using var definition = JsonDocument.Parse(row.DefinitionJson);
                var document = FilterScenarioPayloadParser.ParseDocument(
                    definition.RootElement,
                    prepared.Document.MoneyScale,
                    row.Position);
                var plan = JetAuditProgram.PlanOneScenario(
                    new FilterRequest(action, prepared.ProjectId, [document], prepared.Rule, prepared.Validation),
                    row);
                JetAuditProgram.Finalize(plan, await stores.Facts.ExecuteAsync(plan, cancellationToken));
            }
            else if (change.Removed is not null)
            {
                await stores.Scenarios.RemoveAsync(prepared.ProjectId, change.Removed, cancellationToken);
            }

            if (write.Rows.Count > 0)
            {
                await MappingCommitShared.AdvanceStepAsync(
                    projectStore,
                    prepared.Document,
                    advancesTo,
                    CancellationToken.None,
                    logger);
            }
        }
        else if (write.AllValid)
        {
            var documents = write.Rows.Select(row =>
            {
                using var definition = JsonDocument.Parse(row.DefinitionJson);
                return FilterScenarioPayloadParser.ParseDocument(
                    definition.RootElement,
                    prepared.Document.MoneyScale,
                    row.Position);
            }).ToArray();
            var plan = JetAuditProgram.Plan(
                new FilterRequest(action, prepared.ProjectId, documents, prepared.Rule, prepared.Validation),
                write.Rows);
            var facts = await stores.Facts.ExecuteAsync(plan, cancellationToken);
            var result = JetAuditProgram.Finalize(plan, facts);
            if (result.MaterializedScenarioCount > 0)
            {
                await MappingCommitShared.AdvanceStepAsync(
                    projectStore,
                    prepared.Document,
                    advancesTo,
                    CancellationToken.None,
                    logger);
            }
        }
        else
        {
            await stores.Scenarios.ReplaceAllAsync(prepared.ProjectId, write.Rows, cancellationToken);
        }
    }

    // 寫入已經提交。之後即使請求被取消，也照樣讀回寫入後的狀態放進回應，所以下面不帶呼叫端的取消。
    WorkflowResultStateSupport.CurrentSnapshot? current = null;
    string? reportWarning = null;
    try
    {
        current = await WorkflowResultStateSupport.ReadCurrentAsync(
            prepared.ProjectId,
            stores.Results,
            stores.StaleStates,
            stores.Scenarios,
            CancellationToken.None);
    }
    catch (Exception error)
    {
        if (logger is not null)
            WorkflowResultStateSupport.StateReadFailed(logger, "result_state", error.GetType().Name);
        reportWarning = WorkflowResultStateSupport.MutationStateWarning;
    }

/// <summary>
/// 一次只存、刪或重新檢查一個情境後要寫回的整批。依 <paramref name="batch"/> 現有順序重新編號為 1 到 n，
/// 每一筆都逐筆檢查，讀不出來的情境算成一筆問題，不擋住其他情境。
/// 儲存或移除時，全部沒問題、其他情境都已是目前規則版本，而且 <paramref name="othersResultsCurrent"/>
/// （存好的結果沒有過期）時，其他情境的定義、保存時間與結果都照原樣，只寫這次存或刪的那一個。
/// 其餘情形照整批處理：全部換成同一個保存時間 <paramref name="nowUtc"/>，全部沒問題時整批改用目前規則
/// （名稱、動機與條件不變）；有問題時依 <paramref name="mode"/> 處理其他情境。
/// </summary>
/// <param name="editedPosition">這次編輯的那一個在 <paramref name="batch"/> 裡的位置（從 1 起算）；移除與重新檢查為 null。</param>
internal static FilterScenarioBatchWrite PlanWrite(
    IReadOnlyList<SavedFilterScenario> batch,
    int? editedPosition,
    FilterScenarioWriteMode mode,
    FilterValidationContext validationContext,
    int moneyScale,
    DateTimeOffset nowUtc,
    bool othersResultsCurrent = false)
{
    var ordered = batch
        .Select((scenario, index) => scenario with { Position = index + 1 })
        .ToArray();
    var orderedReview = Review(ordered, validationContext, moneyScale);
    if (Problems(orderedReview).Count == 0
        && mode == FilterScenarioWriteMode.KeepOthersVerbatim
        && othersResultsCurrent
        && orderedReview.All(item => item.Scenario.Position == editedPosition || item.IsCurrentVersion))
    {
        return new FilterScenarioBatchWrite(ordered, true, [], 0) { KeepsOtherResults = true };
    }

