private async Task EnsureCreatedCoreAsync(
    string projectId,
    bool allowCreate,
    Func<CancellationToken, Task<ProtectedProjectSettings>>? settings,
    CancellationToken cancellationToken)
{
    var databasePath = GetDatabasePath(projectId);
    if (!allowCreate)
    {
        // 開案與讀寫只用已經建好的資料庫：檔案不見或是 0 位元組時比照無法開啟的案件回報，
        // 不默默建出空的資料庫。
        LocalSchemaReadiness.RequireDatabaseFile(projectId, databasePath);
    }
    else if (LocalSchemaReadiness.IsEmptyFile(databasePath))
    {
        // 建立時遇到 0 位元組的檔案，只會是建案中斷留下的；連同記錄檔刪掉再建。
        DeleteDatabaseFiles(projectId);
    }

    await using var connection = CreateConnection(projectId);
    await connection.OpenAsync(cancellationToken);

    // 已經建過表的資料庫先和現行結構比對，只讀不寫：缺少不能補上的表或欄位時在任何寫入之前擋下，檔案保持原狀。
    var existing = await HasSchemaInfoAsync(connection, cancellationToken);
    var requiresCompletion = existing && await _projectSchema.CheckAsync(connection, cancellationToken);
    if (!existing && !allowCreate)
    {
        // 有檔案但沒有任何資料表，同樣是沒有內容；在任何寫入之前回報，檔案保持原狀。
        throw LocalSchemaReadiness.EmptyDatabase(projectId);
    }

    // WAL 是存在資料庫檔裡的設定，重複設定沒有影響。用 WAL 以後，一個交易寫入上百萬列時
    // 不必像 rollback journal 那樣把資料寫兩次，取代匯入時的大量 DELETE 也比較快。
    await using (var pragma = connection.CreateCommand())
    {
        pragma.CommandText = "PRAGMA journal_mode=WAL;";
        await pragma.ExecuteNonQueryAsync(cancellationToken);
    }

    if (existing)
    {
        // 缺少的索引、觸發條件，以及首次發布之後新增的表與欄位在這裡補上，之後的讀寫都面對現行結構。
        if (requiresCompletion)
        {
            await _projectSchema.CompleteAsync(connection, cancellationToken);
        }

        return;
    }

    // 案件設定在開交易之前取得，取得時可能要等使用者全名查好。
    var recordedSettings = settings is null ? null : await settings(cancellationToken);

    // 新資料庫在同一個交易裡建好全部的表，中途失敗時不留下只建一半的資料庫。
    await using var transaction = await connection.BeginTransactionAsync(cancellationToken);
    await using (var command = connection.CreateCommand())
    {
        command.Transaction = transaction;
        command.CommandText = _projectSchema.CreateSql;
        await command.ExecuteNonQueryAsync(cancellationToken);
    }

    if (recordedSettings is not null)
    {
        await LocalProjectSettingSql.InsertAsync(connection, transaction, recordedSettings, cancellationToken);
    }

    await transaction.CommitAsync(cancellationToken);
}

/// <summary>
/// 案件資料庫的結構：一份建表程式，加上首次發布之後新增的表與欄位清單。JET 不讀資料庫裡的版本紀錄，只比對結構。
/// 已經建立的案件開啟時，和建表程式建出的表、欄位、索引與觸發條件比對：
/// 全部都在時不寫入任何東西；缺少索引、觸發條件或清單上的表與欄位時，在一個交易裡補上；
/// 缺少清單以外的表或欄位，表示是首次發布以前的 JET 建立的，不開啟，檔案保持原狀。
/// 案件裡多出建表程式沒有的表、欄位或索引時照常開啟，不讀也不改它們。
/// </summary>
internal sealed class ProjectSchema
{
    private readonly Lazy<Task<SchemaShape>> _reference;

    internal ProjectSchema(string createSql, IReadOnlyList<ProjectSchemaAddition> additions)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(createSql);
        ArgumentNullException.ThrowIfNull(additions);
        CreateSql = createSql;
        Additions = additions;
        _reference = new Lazy<Task<SchemaShape>>(BuildReferenceAsync, LazyThreadSafetyMode.ExecutionAndPublication);
    }

    /// <summary>建表程式。每一句都要能在已有資料的案件上重複執行而不改變資料。</summary>
    internal string CreateSql { get; }

    /// <summary>首次發布之後新增的表與欄位，依加入的先後排列；補上時照這個順序執行。</summary>
    internal IReadOnlyList<ProjectSchemaAddition> Additions { get; }

    /// <summary>
    /// 只讀取、不寫入。結構齊全時回 false，需要補上索引、觸發條件或新增的表與欄位時回 true；
    /// 缺少不能補上的表或欄位時，用請審計員刪除後重建的訊息拒絕。
    /// </summary>
    internal async Task<bool> CheckAsync(DbConnection connection, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(connection);
        var plan = await PlanAsync(connection, transaction: null, cancellationToken).ConfigureAwait(false);
        return plan.RequiresCompletion;
    }

    /// <summary>
    /// 在一個交易裡補齊結構：先依清單加上缺少的欄位，再執行建表程式建立缺少的表、索引與觸發條件；
    /// 任何一句失敗，整個交易復原，資料庫保持原狀。取得交易後重新比對一次，另一條連線已經補好時不再執行。
    /// 磁碟已滿、檔案唯讀或損毀這類認得的資料庫錯誤，照一般的資料庫錯誤回報，使用者才知道要處理的是檔案本身；
    /// 另一個程式正在寫入而取不到交易，以及其他失敗，回報開啟失敗，請使用者關閉其他程式後再開啟。
    /// </summary>
    internal async Task CompleteAsync(DbConnection connection, CancellationToken cancellationToken)

