/// 重新匯入時，把目前已確認的配對搬到 <c>field_mapping_previous</c> 再刪除，兩步在匯入的同一個交易裡。
/// 目前沒有已確認的配對時（例如連續匯入兩次都還沒確認）不覆蓋，留著更早那一次確認的配對。
/// SELECT 帶 WHERE，SQLite 才不會把 ON CONFLICT 讀成 join 的一部分。
/// 重新匯入 GL 時，確認配對時存下的日期提醒一起刪掉：提醒說的是舊的 PBC-GL，和已確認的配對同時失效；
/// 上次確認的配對當草稿帶回時不帶提醒。
/// </summary>
internal const string RetireCommittedMappingSql =
    $"""
    INSERT INTO field_mapping_previous
        (dataset_kind, mapping_json, mode_name, source_batch_id, committed_utc, format_version, options_json)
    SELECT dataset_kind, mapping_json, mode_name, source_batch_id, committed_utc, format_version, options_json
    FROM field_mapping
    WHERE dataset_kind = @kind
    ON CONFLICT(dataset_kind) DO UPDATE SET
        mapping_json = excluded.mapping_json,
        mode_name = excluded.mode_name,
        source_batch_id = excluded.source_batch_id,
        committed_utc = excluded.committed_utc,
        format_version = excluded.format_version,
        options_json = excluded.options_json;
    DELETE FROM field_mapping WHERE dataset_kind = @kind;

        FROM gl;
        """;
    command.AddWithValue("@postingStatusReason", GlExcludedPopulation.PostingStatusStorageReason);

    await using var reader = await command.ExecuteReaderLoggedAsync(_log, _provider, cancellationToken);
    await reader.ReadAsync(cancellationToken);

    return new GlPopulationSummary(
        new GlRawPopulationTotals(
            reader.GetInt64(0),
            reader.GetInt64(1),
            reader.GetInt64(2)),
        new ValidationGlTotals(
            reader.GetInt64(3),
            reader.GetInt64(4),
            reader.GetInt64(5),
            reader.GetInt64(6),
            reader.GetInt64(7)),
        new GlExcludedPopulationTotals(
            reader.GetInt64(8),
            reader.GetInt64(9),
            reader.GetInt64(10)));
}

/// <summary>
