    statements.Add($"DELETE FROM {schemaPrefix}import_batch_source WHERE batch_id IN "
        + $"(SELECT batch_id FROM {schemaPrefix}import_batch WHERE dataset_kind = '{kind}');");
    statements.Add($"DELETE FROM {schemaPrefix}import_batch WHERE dataset_kind = '{kind}';");
}
if (impact.InvalidateValidation)
{
    statements.Add($"DELETE FROM {schemaPrefix}validation_result;");
    statements.Add($"DELETE FROM {schemaPrefix}inf_sample;");
}

if (impact.InvalidatePrescreen)
{
    statements.Add($"DELETE FROM {schemaPrefix}prescreen_result;");
}

if (impact.InvalidateFilterHits)
{
    statements.AddRange(FilterHitInsertSql.DeleteAll(schemaPrefix));
    if (impact.InvalidateFilterScenarioDefinitions)
    {
        // 上游修改清除下游：命中先清，再清全部已存情境定義。
        // 兩表之間沒有外鍵，順序只為讓讀者看出命中依附情境。
        statements.Add($"DELETE FROM {schemaPrefix}filter_scenario;");
    }

    var keyColumn = schemaPrefix.Length == 0 ? "key" : "[key]";
    statements.Add($"UPDATE {schemaPrefix}schema_info SET value = CAST(CAST(value AS BIGINT) + 1 AS VARCHAR(40)) "
        + $"WHERE {keyColumn} = 'filter_data_revision';");
}

src/JET/JET/Infrastructure/Sql/FilterHit.excerpt:
/// 寫入一個情境結果的唯一寫法：filter_hit 存命中的分錄，filter_hit_condition 存命中傳票裡每筆分錄符合第幾組第幾條。
/// 儲存一個情境、整批發布與結果過期後重算都經過這裡。
/// 結果在儲存情境時存好，檢視、換頁、展開與匯出都讀它。
/// </summary>
internal static class FilterHitInsertSql
{
    public static string Build(
        string tablePrefix,
        string populationPredicateSql,
        string scenarioPredicateSql) =>
        $"INSERT INTO {tablePrefix}filter_hit (scenario_id, entry_id) "
        + $"SELECT @scenarioId, g.entry_id FROM {tablePrefix}gl g "
        + $"WHERE {populationPredicateSql} AND ({scenarioPredicateSql});";

    /// <summary>
    /// 一條條件在命中傳票裡符合的分錄。只看這個情境已寫入的命中傳票；同一張傳票裡沒命中的分錄也可能符合其中幾條，
    /// 檢視時照樣寫出「符合主要條件」或「整張傳票條件成立」。
    /// </summary>
    public static string BuildCondition(
        string tablePrefix,
        string populationPredicateSql,
        string conditionPredicateSql) =>
        $"INSERT INTO {tablePrefix}filter_hit_condition (scenario_id, entry_id, group_no, condition_no) "
        + $"SELECT @scenarioId, g.entry_id, @groupNo, @conditionNo FROM {tablePrefix}gl g "
        + $"WHERE {populationPredicateSql} AND {HitVoucherRows.InOneSavedScenarioHitVouchers("g", tablePrefix)} "
        + $"AND ({conditionPredicateSql});";

    /// <summary>刪掉一個情境的結果；先刪符合第幾組第幾條，再刪命中。</summary>
    public static IReadOnlyList<string> DeleteOne(string tablePrefix) =>
    [
        $"DELETE FROM {tablePrefix}filter_hit_condition WHERE scenario_id = @scenarioId;",
        $"DELETE FROM {tablePrefix}filter_hit WHERE scenario_id = @scenarioId;"
    ];

    /// <summary>刪掉全部情境的結果。</summary>
    public static IReadOnlyList<string> DeleteAll(string tablePrefix) =>
    [
        $"DELETE FROM {tablePrefix}filter_hit_condition;",
        $"DELETE FROM {tablePrefix}filter_hit;"
    ];

